from pathlib import Path

path = Path("src/tutor_assistant/ui/app.py")
text = path.read_text(encoding="utf-8")

old_import = '''    RecordingHealthSample,\n    RecordingRuntimeRecorder,\n    SystemAudioSourceSnapshot,\n    TranscriptionAudioMissingError,\n'''
new_import = '''    RecordingHealthSample,\n    RecordingRuntimeRecorder,\n    ShutdownCloseAction,\n    ShutdownCoordinator,\n    ShutdownDrainAction,\n    ShutdownRuntimeSnapshot,\n    SystemAudioSourceSnapshot,\n    TranscriptionAudioMissingError,\n'''
if text.count(old_import) != 1:
    raise RuntimeError(f"shutdown import anchor count={text.count(old_import)}")
text = text.replace(old_import, new_import, 1)

old_coordinators = '''        self.normalization_coordinator = NormalizationCoordinator()\n        self.latex_monitor_coordinator = LatexMonitorCoordinator()\n        self._normalization_cancellation: CancellationToken | None = None\n'''
new_coordinators = '''        self.normalization_coordinator = NormalizationCoordinator()\n        self.latex_monitor_coordinator = LatexMonitorCoordinator()\n        self.shutdown_coordinator = ShutdownCoordinator()\n        self._normalization_cancellation: CancellationToken | None = None\n'''
if text.count(old_coordinators) != 1:
    raise RuntimeError(f"coordinator init anchor count={text.count(old_coordinators)}")
text = text.replace(old_coordinators, new_coordinators, 1)

old_flags = '''        self._loading_segments = False\n        self._summary_dirty = False\n        self._shutdown_requested = False\n        self._shutdown_ready = False\n        self.transcription_worker = TranscriptionWorker(self.pipeline)\n'''
new_flags = '''        self._loading_segments = False\n        self._summary_dirty = False\n        self.transcription_worker = TranscriptionWorker(self.pipeline)\n'''
if text.count(old_flags) != 1:
    raise RuntimeError(f"legacy shutdown flags anchor count={text.count(old_flags)}")
text = text.replace(old_flags, new_flags, 1)

old_shutdown = '''    def closeEvent(self, event: QCloseEvent) -> None:\n        self.playback_controller.stop(clear_source=True)\n        if self._shutdown_ready:\n            event.accept()\n            return\n        has_recording = bool(self.recorder and self.recorder.active) or self._recording_stop_started\n        has_workers = any(worker.isRunning() for worker in self.workers) or self.transcription_worker.busy\n        if not has_recording and not has_workers:\n            self.transcription_worker.shutdown()\n            if self.transcription_worker.wait(1000):\n                event.accept()\n            else:\n                self._shutdown_requested = True\n                event.ignore()\n            return\n        answer = QMessageBox.question(\n            self,\n            "Безопасное завершение",\n            "Сначала завершить запись и дождаться текущих фоновых операций? "\n            "Ожидающие транскрибации сохранятся и продолжатся при следующем запуске.",\n            QMessageBox.Yes | QMessageBox.Cancel,\n            QMessageBox.Yes,\n        )\n        if answer != QMessageBox.Yes:\n            event.ignore()\n            return\n        event.ignore()\n        self._shutdown_requested = True\n        if self._normalization_cancellation is not None:\n            self._normalization_cancellation.cancel()\n        self.transcription_worker.shutdown()\n        self.timer.stop()\n        self.latex_poll_timer.stop()\n        self.content_maintenance_timer.stop()\n        self.quick_countdown_timer.stop()\n        self.start_button.setEnabled(False)\n        self.quick_start_button.setEnabled(False)\n        self._set_status("Завершаю текущие операции…", "working")\n        if self.recorder and self.recorder.active and not self._recording_stop_started:\n            self._stop_recording_async("Приложение закрывается; запись корректно завершается")\n        self._maybe_finish_shutdown()\n\n    def _maybe_finish_shutdown(self) -> None:\n        if not self._shutdown_requested:\n            return\n        recording_busy = bool(self.recorder and self.recorder.active) or self._recording_stop_started\n        workers_busy = any(worker.isRunning() for worker in self.workers)\n        if recording_busy or workers_busy or self.transcription_worker.isRunning():\n            return\n        self._shutdown_ready = True\n        QTimer.singleShot(0, self.close)\n'''
new_shutdown = '''    def _shutdown_runtime_snapshot(self) -> ShutdownRuntimeSnapshot:\n        return ShutdownRuntimeSnapshot(\n            recording_active=bool(self.recorder and self.recorder.active),\n            recording_stop_in_flight=self._recording_stop_started,\n            workers_running=any(worker.isRunning() for worker in self.workers),\n            transcription_busy=self.transcription_worker.busy,\n            transcription_running=self.transcription_worker.isRunning(),\n            normalization_cancellable=self._normalization_cancellation is not None,\n        )\n\n    def _begin_shutdown_drain(self, snapshot: ShutdownRuntimeSnapshot) -> None:\n        plan = self.shutdown_coordinator.confirm_close(snapshot, confirmed=True)\n        if not plan.begin_draining:\n            return\n        if plan.cancel_normalization and self._normalization_cancellation is not None:\n            self._normalization_cancellation.cancel()\n        if plan.shutdown_transcription:\n            self.transcription_worker.shutdown()\n        if plan.quiesce_runtime:\n            self.timer.stop()\n            self.latex_poll_timer.stop()\n            self.content_maintenance_timer.stop()\n            self.quick_countdown_timer.stop()\n            self.start_button.setEnabled(False)\n            self.quick_start_button.setEnabled(False)\n            self._set_status("Завершаю текущие операции…", "working")\n        if plan.finalize_recording:\n            self._stop_recording_async(\n                "Приложение закрывается; запись корректно завершается"\n            )\n\n    def closeEvent(self, event: QCloseEvent) -> None:\n        self.playback_controller.stop(clear_source=True)\n        snapshot = self._shutdown_runtime_snapshot()\n        decision = self.shutdown_coordinator.request_close(snapshot)\n\n        if decision.action == ShutdownCloseAction.ACCEPT:\n            event.accept()\n            return\n        if decision.action == ShutdownCloseAction.IGNORE:\n            event.ignore()\n            return\n        if decision.action == ShutdownCloseAction.TRY_IMMEDIATE:\n            self.transcription_worker.shutdown()\n            stopped = self.transcription_worker.wait(decision.transcription_wait_ms or 0)\n            self.shutdown_coordinator.complete_immediate_shutdown(\n                transcription_stopped=stopped\n            )\n            if stopped:\n                event.accept()\n            else:\n                event.ignore()\n            return\n\n        if decision.action != ShutdownCloseAction.PROMPT:\n            event.ignore()\n            return\n        answer = QMessageBox.question(\n            self,\n            "Безопасное завершение",\n            "Сначала завершить запись и дождаться текущих фоновых операций? "\n            "Ожидающие транскрибации сохранятся и продолжатся при следующем запуске.",\n            QMessageBox.Yes | QMessageBox.Cancel,\n            QMessageBox.Yes,\n        )\n        if answer != QMessageBox.Yes:\n            self.shutdown_coordinator.confirm_close(snapshot, confirmed=False)\n            event.ignore()\n            return\n\n        event.ignore()\n        self._begin_shutdown_drain(self._shutdown_runtime_snapshot())\n        self._maybe_finish_shutdown()\n\n    def _maybe_finish_shutdown(self) -> None:\n        action = self.shutdown_coordinator.observe_drain(\n            self._shutdown_runtime_snapshot()\n        )\n        if action == ShutdownDrainAction.SCHEDULE_CLOSE:\n            QTimer.singleShot(0, self.close)\n'''
if text.count(old_shutdown) != 1:
    raise RuntimeError(f"shutdown block anchor count={text.count(old_shutdown)}")
text = text.replace(old_shutdown, new_shutdown, 1)

if "_shutdown_requested" in text or "_shutdown_ready" in text:
    raise RuntimeError("legacy shutdown flags remain after migration")
if text.count("self.shutdown_coordinator = ShutdownCoordinator()") != 1:
    raise RuntimeError("shutdown coordinator init missing")
if text.count("def _shutdown_runtime_snapshot") != 1:
    raise RuntimeError("shutdown runtime snapshot missing")
if text.count("def _begin_shutdown_drain") != 1:
    raise RuntimeError("shutdown drain adapter missing")

path.write_text(text, encoding="utf-8")
